def main() -> None:
    if not SOURCE.is_file():
        raise SystemExit(f'Missing frozen input: {SOURCE}')
    records = json.loads(SOURCE.read_text(encoding='utf-8'))
    if len(records) != 42 or [r.get('slide') for r in records] != list(range(1, 43)):
        raise SystemExit('Frozen input must contain slide records 1–42 in order.')
    original_titles = {n: records[n-1]['title'] for n in range(1, 43)}
    protected = {n: json.dumps(records[n-1], ensure_ascii=False, sort_keys=True) for n in range(35, 43)}
    for n, lang_edits in EDIT.items():
        record = records[n-1]
        if n <= 15 and record['title'] != original_titles[n]:
            raise SystemExit(f'Unexpected slide-title state at {n}')
        if n == 16:
            record['title'] = 'The retained recipe survives performance and quality checks'
        if n == 19:
            record['title'] = 'Backup · full-set accuracy verification'
        for lang, fields in lang_edits.items():
            record.setdefault(lang, {}).update(fields)
    for n, languages in POST.items():
        for lang, fields in languages.items():
            records[n-1].setdefault(lang, {}).update(fields)
    # Some main records had prose but no five-part reasoning object.
    # Reuse their own source fields; this is a structural restatement, not a
    # reconstruction of undocumented motives.
    for n in range(1, 17):
        for lang in ('en', 'vi'):
            section = records[n-1][lang]
            if 'reasoning' not in section:
                tradeoff = section['tradeoff']
                obs = tradeoff.get('observation', '')
                conclusion = tradeoff.get('conclusion', '')
                hypothesis = tradeoff.get('hypothesis', '')
                unknown = tradeoff.get('unknown', '')
                section['reasoning'] = {
                    'problem': section['purpose'],
                    'why_it_matters': hypothesis or unknown or section['caution'],
                    'why_this_test': section['visual'],
                    'what_we_learned': ' '.join(x for x in (obs, conclusion) if x),
                    'next_logic': section['transition'],
                }
    for n in range(1, 17):
        for lang in ('en', 'vi'):
            tradeoff = records[n-1][lang].get('tradeoff')
            if not isinstance(tradeoff, dict):
                raise SystemExit(f'Slide {n} {lang} needs structured tradeoff evidence.')
            for key in ('observation', 'hypothesis', 'conclusion', 'unknown'):
                if key not in tradeoff:
                    raise SystemExit(f'Slide {n} {lang} tradeoff is missing {key}.')
            reasoning = records[n-1][lang].get('reasoning', {})
            for key in ('problem', 'why_it_matters', 'why_this_test', 'what_we_learned', 'next_logic'):
                if key not in reasoning:
                    raise SystemExit(f'Slide {n} {lang} reasoning is missing {key}.')
    for n in range(1, 16):
        if records[n-1]['title'] != original_titles[n]:
            raise SystemExit(f'Maintitle {n} changed unexpectedly')
    for n in range(35, 43):
        if json.dumps(records[n-1], ensure_ascii=False, sort_keys=True) != protected[n]:
            raise SystemExit(f'Protected HPC slide {n} was modified')
    TARGET.write_text(json.dumps(records, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
    print(f'Wrote {TARGET}')
    print('Updated AI records 1–15, 16 and 19; preserved HPC records 35–42.')

if __name__ == '__main__':
    main()
